const sha=v=>require('crypto').createHash('sha256').update(typeof v==='string'?v:JSON.stringify(v),'utf8').digest('hex');
const articleHash=a=>sha([a.title,a.content_html,a.seo_title,a.meta_description,a.slug,a.keyword,a.category_id??null,a.existing_tag_ids??[]]);
const plainBody=h=>String(h||'').replace(/<!--[\s\S]*?-->/g,'').replace(/<figure\b[^>]*>[\s\S]*?<\/figure>/gi,'').replace(/<img\b[^>]*>/gi,'').replace(/>\s+</g,'><').replace(/\r\n/g,'\n').trim();
const imageSources=h=>[...String(h||'').matchAll(/<img\b[^>]*\bsrc=["']([^"']+)["']/gi)].map(m=>m[1].replace(/&amp;/g,'&'));
const s=JSON.parse(JSON.stringify($json.state||$json));
if(s.writer_policy_version==='nehad-whole-article-v5'){
 if(s.decision!=='approve'||s.approval_audit?.decision!=='approve'||s.approved_article_hash!==articleHash(s.article)||s.approved_image_hash!==sha(s.images||[]))throw Error('The current article/images do not match the human-approved version.');
}
s.approved_content_hash=articleHash(s.article);
s.approved_revision_hash=sha([s.approved_content_hash,sha(s.images||[])]);
return [{json:s,...($binary?{binary:$binary}:{}),pairedItem:{item:0}}];

const sha=v=>require('crypto').createHash('sha256').update(typeof v==='string'?v:JSON.stringify(v),'utf8').digest('hex');
const articleHash=a=>sha([a.title,a.content_html,a.seo_title,a.meta_description,a.slug,a.keyword,a.category_id??null,a.existing_tag_ids??[]]);
const plainBody=h=>String(h||'').replace(/<!--[\s\S]*?-->/g,'').replace(/<figure\b[^>]*>[\s\S]*?<\/figure>/gi,'').replace(/<img\b[^>]*>/gi,'').replace(/>\s+</g,'><').replace(/\r\n/g,'\n').trim();
const imageSources=h=>[...String(h||'').matchAll(/<img\b[^>]*\bsrc=["']([^"']+)["']/gi)].map(m=>m[1].replace(/&amp;/g,'&'));
const s=JSON.parse(JSON.stringify($('Normalize WordPress Input').item.json)),list=$json.body;
if(!Array.isArray(list))throw Error('Unexpected WordPress lookup response');
s.marker='<!-- n8n-legal-topic:'+s.topic.topic_id+' -->';s.revision_marker='<!-- n8n-legal-revision:'+(s.approved_revision_hash||s.approved_content_hash)+' -->';
if(list.length>1)throw Error('Ambiguous WordPress slug: multiple posts require reconciliation');
s.already_created=false;
if(list.length){const p=list[0],body=String(p.content?.raw||'');
 if(p.status!=='draft'||!body.includes(s.marker))throw Error('This slug belongs to an unrelated or published post.');
 s.wp_post_id=p.id;s.wp_url=s.settings.site_url+'/?p='+p.id+'&preview=true';
 const same=plainBody(body)===plainBody(s.article.content_html)&&body.includes(s.revision_marker)&&(body.match(/<img\b/gi)||[]).length===3&&Number(p.featured_media)>0;
 s.already_created=same;s.wp_update_existing=!same;s.draft_integrity={revision_hash:s.approved_content_hash,existing_body_matches:same};
}
return [{json:s}];

const s=JSON.parse(JSON.stringify($json));if(!s.wp_post_id||!s.wp_url)throw new Error('Missing confirmed draft');
if(!s.approved.some(a=>a.topic_id===s.topic.topic_id)){s.approved_count++;s.approved.push({topic_id:s.topic.topic_id,title:s.article.title,url:s.wp_url});}
s.reason='Approved version '+s.review_token;
const draftMessage=[
'تم إنشاء مسودة WordPress بعد الموافقة.',
String(s.article.title),
'رابط المعاينة (يتطلب تسجيل دخول):',
s.wp_url,
'رابط التحرير:',
s.settings.wp_admin_url+'/post.php?post='+s.wp_post_id+'&action=edit',
s.rankmath_warning||'Rank Math: يلزم فتح المسودة للتحقق من الدرجة الفعلية؛ الهدف 95/100.',
s.review_warning?'⚠️ ملاحظات المراجعة محفوظة في تقرير المقال؛ لم تمنع إنشاء المسودة.':'',
'الدفعة: '+s.batch_id+' — تم تأكيد مسودة هذا المقال'
].filter(Boolean).join('\n');
s.draft_notification_html=draftMessage.slice(0,3800).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return [{json:s}];

const s=$json;
if(s.decision!=='approve'||!(s.ready_for_review === true || (s.ready_for_review === undefined && s.passed === true)))throw new Error('Latest human approval required');
if(!Array.isArray(s.images)||s.images.length!==4)throw new Error('Approved package must have four images');
const out=[];
for(const im of s.images){
 im.file_name=String(s.topic.topic_id).replace(/[^A-Za-z0-9_-]/g,'-')+'-'+s.reservation_token+'-v'+s.revision+'-'+im.role+'.webp';
 const image=await this.helpers.prepareBinaryData(Buffer.from(im.base64,'base64'),im.file_name,'image/webp');
 const {base64,...metadata}=im;
 out.push({json:{settings:s.settings,article:{title:s.article.title},image:metadata},binary:{image},pairedItem:{item:0}});
}
return out;

const s=JSON.parse(JSON.stringify($('Check Draft Idempotency').itemMatching(0).json));
if(s.decision!=='approve'||!(s.ready_for_review === true || (s.ready_for_review === undefined && s.passed === true)))throw new Error('Latest approval required');
const items=$input.all();if(items.length!==4)throw new Error('Four media uploads required');
const media=items.map((x,i)=>{
 const image=$('Prepare Approved Image').itemMatching(i).json.image,p=x.json;
 if(!Number.isInteger(p.id)||p.id<=0||typeof p.source_url!=='string'||!p.source_url.startsWith(s.settings.site_url+'/'))throw new Error('Media upload not confirmed');
 return {...image,id:p.id,url:p.source_url};
});
if(new Set(media.map(m=>m.role)).size!==4)throw new Error('Duplicate media role');
const featured=media.find(m=>m.role==='featured');if(!featured)throw new Error('Missing featured image');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let content=s.article.content_html;
for(const im of media.filter(x=>x.role!=='featured')){
 const marker='<!-- ARTICLE_IMAGE_'+im.index+' -->';
 if(!content.includes(marker))throw new Error('Missing inline image slot '+im.index);
 content=content.replace(marker,'<figure class="wp-block-image size-full"><img src="'+esc(im.url)+'" alt="'+esc(im.alt_text)+'" width="1200" height="630" class="wp-image-'+im.id+'" loading="lazy" decoding="async"></figure>');
}
if(/ARTICLE_IMAGE_/.test(content)||(content.match(/<img\b/g)||[]).length!==3)throw new Error('Invalid inline image count');
const a=s.article;
const tagNames=(a.existing_tag_ids||[]).map(id=>s.taxonomy.tags.find(t=>Number(t.id)===Number(id))?.name);
if(tagNames.some(x=>!x))throw new Error('Unknown tag ID');
s.wp_media_id=featured.id;s.wp_images=media;s.article.content_html=content;
s.wp_payload={status:'draft',title:a.title,slug:a.slug,post_content:s.marker+'\n'+s.revision_marker+'\n'+content,excerpt:a.meta_description,rankmath_title:a.seo_title,rankmath_description:a.meta_description,categories:[Number(a.category_id)],tags:[...new Set(tagNames)]};
s.wp_expected_content=s.wp_payload.post_content;s.wp_expected_text_hash=require('crypto').createHash('sha256').update(s.wp_expected_content,'utf8').digest('hex');
return [{json:s,pairedItem:{item:0}}];

const s=JSON.parse(JSON.stringify($('Prepare WordPress Draft').item.json));
const b=$json.body??$json;if(b.success===false)throw new Error('Custom API rejected creation');
const id=Number(b.data?.id??b.data?.post_id??b.post_id??b.id);
if(!Number.isInteger(id)||id<1)throw new Error('Custom API returned no post ID; inspect the response before retrying to avoid duplicates');
s.wp_post_id=id;return [{json:s}];

const sha=v=>require('crypto').createHash('sha256').update(typeof v==='string'?v:JSON.stringify(v),'utf8').digest('hex');
const articleHash=a=>sha([a.title,a.content_html,a.seo_title,a.meta_description,a.slug,a.keyword,a.category_id??null,a.existing_tag_ids??[]]);
const plainBody=h=>String(h||'').replace(/<!--[\s\S]*?-->/g,'').replace(/<figure\b[^>]*>[\s\S]*?<\/figure>/gi,'').replace(/<img\b[^>]*>/gi,'').replace(/>\s+</g,'><').replace(/\r\n/g,'\n').trim();
const imageSources=h=>[...String(h||'').matchAll(/<img\b[^>]*\bsrc=["']([^"']+)["']/gi)].map(m=>m[1].replace(/&amp;/g,'&'));
const s=JSON.parse(JSON.stringify($('Read Custom Post Result').item.json));const body=String($json.content?.raw||'');
if(Number($json.id)!==s.wp_post_id||$json.status!=='draft'||!body.includes(s.marker)||!body.includes(s.revision_marker))throw Error('Stored post is not the intended approved draft revision.');
if(plainBody(body)!==plainBody(s.wp_expected_content)||(body.match(/<img\b/gi)||[]).length!==3)throw Error('WordPress body does not match the approved content or images. Saved article remains in execution data.');
if(JSON.stringify(imageSources(body))!==JSON.stringify(imageSources(s.wp_expected_content))||Number($json.featured_media)!==s.wp_media_id)throw Error('Stored images do not match approved uploaded images.');
s.draft_integrity={revision_hash:s.approved_content_hash,body_matches:true,inline_images:3,checked_at:new Date().toISOString()};return [{json:s}];

const s=JSON.parse(JSON.stringify($('Validate Created Draft').item.json));
if(Number($json.id)!==s.wp_post_id||$json.status!=='draft'||Number($json.featured_media)!==s.wp_media_id)throw new Error('WordPress did not confirm draft and approved featured image');
let storedSlug='';try{storedSlug=decodeURIComponent(String($json.slug||'')).normalize('NFC');}catch(e){}
s.seo_preflight={...(s.seo_preflight||{}),stored_slug:storedSlug,stored_slug_verified:storedSlug.replace(/-/g,' ').replace(/\s+/g,' ').includes(String(s.article.keyword).normalize('NFC').replace(/\s+/g,' ').trim())};
if(!s.seo_preflight.stored_slug_verified)s.review_warning_text=(s.review_warning_text||'')+'\nتنبيه: WordPress لم يؤكد تطابق الكلمة المفتاحية في الرابط المحفوظ؛ راجع slug في المحرر.';
s.wp_url=s.settings.site_url+'/?p='+s.wp_post_id+'&preview=true';s.rankmath_payload={objectType:'post',objectID:Number(s.wp_post_id),meta:{rank_math_title:s.article.seo_title,rank_math_description:s.article.meta_description,rank_math_focus_keyword:s.article.keyword}};
return [{json:s}];

const s=JSON.parse(JSON.stringify($('Verify Draft Created').item.json));
const status=Number($json.statusCode||0);
const body=$json.body;
const sent=status>=200&&status<300&&!$json.error&&!(body&&typeof body==='object'&&(body.error||body.code||body.success===false));
s.rankmath={target:95,score:null,metadata_saved:sent,metadata_verified:false,save_http_status:status||null,status:'NOT_MEASURED',note:'لم تُحسب درجة Rank Math بعد داخل محرر WordPress.'};
if(!sent)s.rankmath.note='تعذر تأكيد حفظ حقول Rank Math. HTTP '+(status||'unavailable')+'. '+String($json.error?.message||$json.error||body?.message||'').slice(0,240);
delete s.rankmath_payload;
return [{json:s}];

const s=JSON.parse(JSON.stringify($('Keep Rank Math Save Result').item.json));
const status=Number($json.statusCode||0);
const p=$json.body;
const ok=status>=200&&status<300&&p&&typeof p==='object'&&Number(p.post_id)===Number(s.wp_post_id)&&!p.error;
s.rankmath.metadata_verified=false;
s.rankmath.target_verified=false;
if(ok){
 const norm=v=>String(v??'').trim();
 const expected={title:s.article.seo_title,description:s.article.meta_description,focus_keyword:s.article.keyword};
 const mismatches=Object.keys(expected).filter(k=>!norm(expected[k])||norm(p[k])!==norm(expected[k]));
 s.rankmath.metadata_verified=mismatches.length===0;
 s.rankmath.metadata_mismatches=mismatches;
 const raw=p.seo_score;
 const score=(typeof raw==='number'||(typeof raw==='string'&&raw.trim()!==''))?Number(raw):NaN;
 if(Number.isFinite(score)&&score>=0&&score<=100){
  s.rankmath.score=score;s.rankmath.status='STORED_SCORE';
  s.rankmath.note='الدرجة المحفوظة في Rank Math: '+score+'/100؛ ليست إعادة حساب جديدة، وقد تختلف عن درجة المحرر. الهدف 95/100 غير مُتحقق بعد.';
 }else{
  s.rankmath.score=null;s.rankmath.status='NOT_MEASURED';
  s.rankmath.note='تمت قراءة حقول Rank Math لكن لا توجد درجة محفوظة صالحة؛ افتح محرر WordPress لقياس الدرجة الفعلية.';
 }
 if(mismatches.length)s.rankmath.note+=' حقول SEO غير مؤكدة أو غير مطابقة: '+mismatches.join(', ')+'.';
}else{
 s.rankmath.score=null;s.rankmath.status='READ_FAILED';
 s.rankmath.note=status===403?'رفضت أداة Rank Math قراءة بيانات هذه المسودة (403). يلزم فحص صلاحيات الأداة دون تغييرها تلقائياً.':'تعذر التحقق من بيانات Rank Math للمسودة المطلوبة. HTTP '+(status||'unavailable')+'.';
}
if(!s.rankmath.metadata_saved)s.rankmath.note+=' طلب حفظ حقول SEO لم يُؤكد نجاحه؛ راجع نتيجة القراءة.';

if(s.seo_preflight?.stored_slug_verified===false)s.rankmath.note+=' تنبيه: الرابط المحفوظ لا يتضمن الكلمة المفتاحية حرفيًا؛ راجع slug في WordPress.';
s.rankmath_warning='Rank Math: '+s.rankmath.note;
if(s.seo_preflight)s.rankmath_warning+='\nفحص المحتوى (ليس درجة Rank Math): كثافة الكلمة '+s.seo_preflight.approx_keyword_density+'%، عددها '+s.seo_preflight.exact_keyword_occurrences+'، رقم بعنوان SEO '+(s.seo_preflight.seo_title_has_number?'نعم':'لا')+'، تطابق الرابط المحفوظ '+(s.seo_preflight.stored_slug_verified?'نعم':'غير مؤكد')+'.';

return [{json:s}];
